def all_variants():
    """Yield (page, variant_number, variant) in posting-priority order: all v1s, then v2s, then v3s."""
    for n in range(3):
        for page in PAGES:
            vs = VARIANTS[page["key"]]
            if n < len(vs):
                yield page, n + 1, vs[n]
